    async def receive_saml_sso_response(
        self,
        *,
        SAMLResponse: str,
        extra_body: Optional[Mapping[str, Any]] = None,
    ) -> httpx.Response:
        """Receive the SAML SSO response.

        Receive the authentication response of the SAML identity provider. If
        SAML_SUBJECT_ATTRIBUTE is set, this route logs in the person linked to the
        issuer and the subject of the assertion. The email finds the account at the
        first login only. If no person has this email, a new person is created.

        Args:
            SAMLResponse: SAML response of the identity provider, base64 encoded

        ``POST /auth/saml/sso``
        """
        return await self._t.request(
            "POST",
            "/auth/saml/sso",
            body={"SAMLResponse": SAMLResponse},
            extra_body=extra_body,
            body_mode="form",
            raw=True,
        )

    async def start_saml_sso_login(self) -> httpx.Response:
        """Start the SAML SSO login.

        Start an SSO login. This route redirects to the SAML identity provider.

        ``GET /auth/saml/login``
        """
        return await self._t.request("GET", "/auth/saml/login", raw=True)

    async def start_oidc_sso_login(self) -> httpx.Response:
        """Start the OIDC SSO login.

        Start an SSO login. This route redirects to the OpenID Connect identity
        provider.

        ``GET /auth/oidc/login``
        """
        return await self._t.request("GET", "/auth/oidc/login", raw=True)

    async def receive_oidc_sso_callback(self) -> httpx.Response:
        """Receive the OIDC SSO callback.

        Receive the response of the OpenID Connect identity provider. This route changes
        the authorization code into tokens and validates the ID token. Then, it logs in
        the person linked to the issuer and the subject of the token. At the first
        login, the person with the email of the token is linked to this identity. If no
        person has this email, a new person is created.

        ``GET /auth/oidc/callback``
        """
        return await self._t.request("GET", "/auth/oidc/callback", raw=True)
